#!/usr/bin/env node
// Runs every pipeline scenario and writes a readable log of what happened.
// npm run agent:scenarios  ->  docs/PIPELINE_SCENARIOS.md
import { mkdirSync, writeFileSync } from "node:fs";
import { SCENARIOS } from "./scenarios.mjs";

const lines = [
  "# Pipeline scenarios",
  "",
  "Generated by `npm run agent:scenarios`. Each scenario drives the real decision code",
  "(`.github/agent/*.mjs`) through a simulated GitHub, with scripted agent, CI and review results.",
  "The same scenarios run in `npm test`, so this file can't drift from the behaviour.",
  "",
];
let failed = 0;
for (const [i, s] of SCENARIOS.entries()) {
  let sim = null;
  let error = null;
  try {
    sim = await s.run();
  } catch (e) {
    error = e;
    failed++;
  }
  lines.push(`## ${i + 1}. ${s.name}`, "", error ? `**FAILED:** ${error.message.split("\n")[0]}` : "**Result:** passed", "");
  if (sim?.log?.length) {
    lines.push("```");
    for (const l of sim.log) lines.push(l);
    lines.push("```", "");
  }
}
mkdirSync("docs", { recursive: true });
writeFileSync("docs/PIPELINE_SCENARIOS.md", lines.join("\n"));
console.log(`${SCENARIOS.length - failed}/${SCENARIOS.length} scenarios passed -> docs/PIPELINE_SCENARIOS.md`);
process.exitCode = failed ? 1 : 0;
